import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"Building, Publishing, and Running an Extension","description":"","frontmatter":{},"headers":[],"relativePath":"your-first-al-programs/building-publishing-and-running-an-extension.md","filePath":"your-first-al-programs/building-publishing-and-running-an-extension.md"}`),a={name:`your-first-al-programs/building-publishing-and-running-an-extension.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="building-publishing-and-running-an-extension" tabindex="-1">Building, Publishing, and Running an Extension <a class="header-anchor" href="#building-publishing-and-running-an-extension" aria-label="Permalink to “Building, Publishing, and Running an Extension”">​</a></h1><p>When developing AL extensions for Business Central, we typically follow three steps: <strong>build, publish, and run</strong>.</p><h2 id="_1-building-an-extension" tabindex="-1">1. Building an Extension <a class="header-anchor" href="#_1-building-an-extension" aria-label="Permalink to “1. Building an Extension”">​</a></h2><p>Building compiles your AL code and checks it for errors.</p><ul><li>The AL compiler checks your code against AL syntax and type rules.</li><li>If compilation succeeds, it generates an <code>.app</code> package containing your extension.</li><li>If errors are found, fix them before publishing.</li></ul><p><strong>In VS Code:</strong></p><ul><li>Press <code>Ctrl + Shift + B</code> to build the project.</li></ul><h2 id="_2-publishing-an-extension" tabindex="-1">2. Publishing an Extension <a class="header-anchor" href="#_2-publishing-an-extension" aria-label="Permalink to “2. Publishing an Extension”">​</a></h2><p>Publishing deploys your extension to a Business Central environment, making its functionality available there.</p><p>When you publish an extension from VS Code, the development workflow builds and uploads the extension to the configured Business Central environment.</p><p><strong>In VS Code:</strong></p><ul><li>Press <code>Ctrl + F5</code> to publish and run without debugging.</li><li>Press <code>F5</code> to publish and start a debugging session.</li></ul><p>Publishing requires a correctly configured <code>launch.json</code> and access to the target environment.</p><h2 id="_3-running-an-extension" tabindex="-1">3. Running an Extension <a class="header-anchor" href="#_3-running-an-extension" aria-label="Permalink to “3. Running an Extension”">​</a></h2><p>Running means executing the functionality provided by your extension.</p><p><strong>Important:</strong> Publishing an extension does not automatically execute all its AL code.</p><p>For example, if your extension adds an action to the Customer List page, you must open that page and select the action to execute its code.</p><p>Triggers execute when their corresponding events occur. For example, <code>OnOpenPage()</code> executes when its page opens.</p><h2 id="quick-summary" tabindex="-1">Quick Summary <a class="header-anchor" href="#quick-summary" aria-label="Permalink to “Quick Summary”">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Purpose</th><th>VS Code shortcut</th></tr></thead><tbody><tr><td>Build</td><td>Compile code and generate the extension package.</td><td><code>Ctrl + Shift + B</code></td></tr><tr><td>Publish without debugging</td><td>Deploy the extension and open the configured browser session when enabled.</td><td><code>Ctrl + F5</code></td></tr><tr><td>Publish with debugging</td><td>Deploy the extension and start a debugging session.</td><td><code>F5</code></td></tr><tr><td>Run functionality</td><td>Execute the extension&#39;s code through a trigger, action, or other execution mechanism.</td><td>Depends on the functionality</td></tr></tbody></table><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to “Further Reading”">​</a></h2><ul><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-get-started" target="_blank" rel="noreferrer">Getting started with AL — Microsoft Learn</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-debugging" target="_blank" rel="noreferrer">Debugging AL code — Microsoft Learn</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-json-launch-file" target="_blank" rel="noreferrer">The <code>launch.json</code> file — Microsoft Learn</a></li></ul>`,22)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};